def fib(n, memo={}):
    if n < 2:
        return n
    if n not in memo:
        memo[n] = fib(n - 1, memo) + fib(n - 2, memo)
    return memo[n]

first = fib(10)
sizes = len(fib.__defaults__[0])
second = fib(12)
print(first, second, sizes, len(fib.__defaults__[0]))

