prog = [('push', 3), ('push', 4), ('add',), ('push', 2), ('mul',),
        ('dup',), ('push', 5), ('sub',), ('push', 10), ('swap',), ('div',)]
st = []
for op in prog:
    if op[0] == 'push': st.append(op[1])
    elif op[0] == 'add': b, a = st.pop(), st.pop(); st.append(a + b)
    elif op[0] == 'mul': b, a = st.pop(), st.pop(); st.append(a * b)
    elif op[0] == 'sub': b, a = st.pop(), st.pop(); st.append(a - b)
    elif op[0] == 'dup': st.append(st[-1])
    elif op[0] == 'swap': st[-1], st[-2] = st[-2], st[-1]
    elif op[0] == 'div': b, a = st.pop(), st.pop(); st.append(a // b if b else 0)
print(st)

class State:
    name = 'base'
    def on(self, ev):
        return self if ev == 'noop' else Error()
class Idle(State):
    name = 'idle'
    def on(self, ev):
        return Running() if ev == 'start' else super().on(ev)
class Running(State):
    name = 'running'
    def on(self, ev):
        if ev == 'pause': return Paused()
        if ev == 'stop': return Idle()
        return super().on(ev)
class Paused(Running):
    name = 'paused'
    def on(self, ev):
        return Running() if ev == 'start' else super().on(ev)
class Error(State):
    name = 'error'

