def walk(x, d=0):
    if not isinstance(x, list):
        return d, 1, x
    if not x:
        return d, 0, 0
    results = [walk(i, d + 1) for i in x]
    return (max(r[0] for r in results),
            sum(r[1] for r in results),
            sum(r[2] for r in results))
